process_schema.body:
Get the processes running in the terminal and how its program exited.

Method: com.superlogical.terminal.process

Input schema:
{
  "type": "object",
  "additionalProperties": false
}

Output schema:
{
  "type": "object",
  "properties": {
    "ancestors": {
      "type": [
        "null",
        "array"
      ],
      "items": {
        "type": "object",
        "properties": {
          "argv0": {
            "type": "string",
            "description": "The first argument as the process shows it now, such as -zsh for a login shell, cut to 256 bytes. Rex never returns the other arguments, because they can hold secrets."
          },
          "cwd": {
            "type": "string",
            "description": "The process's working directory, as an absolute path. Left out if it can't be read, as for another user's process."
          },
          "invoked_path": {
            "type": "string",
            "description": "The absolute path the executable was started through, before symlinks were resolved, such as a link in a bin directory. Present only when Rex can confirm it leads to the same file as path."
          },
          "name": {
            "type": "string",
            "description": "The file name of the executable, such as zsh. When path is left out, the system's own name for the process, which Linux limits to 15 bytes. To label a process, use the first of script, argv0, and name that is present."
          },
          "path": {
            "type": "string",
            "description": "The absolute path of the executable, with symlinks resolved. Left out if it can't be read, as for another user's process on Linux."
          },
          "pid": {
            "type": "integer",
            "description": "The process ID."
          },
          "script": {
            "type": "string",
            "description": "For an interpreter such as node or python, the absolute path of the script it is running, as the user named it. Left out for other programs."
          },
          "user": {
            "type": "string",
            "description": "The name of the account the process runs as. Left out if it can't be looked up."
          },
          "user_id": {
            "type": "integer",
            "description": "The user ID the process runs as on Unix, which shows when a command runs as another user, such as with sudo. Zero on Windows."
          }
        },
        "required": [
          "pid",
          "user_id",
          "name"
        ],
        "additionalProperties": false
      },
      "description": "The processes between foreground and child, nearest first: the parent of foreground, then its parent, and so on, ending with child. Left out when foreground is child, when there are more than 16, or when one of them has exited."
    },
