        "name"
      ],
      "additionalProperties": false
    },
    "home": {
      "type": "string",
      "description": "The home directory that the terminal's program inherited, for showing and expanding ~ in paths."
    },
    "last_exit": {
      "type": [
        "null",
        "object"
      ],
      "properties": {
        "error": {
          "type": "string",
          "description": "Why the program failed, such as 'exit status 1'. Left out when it exited successfully."
        },
        "exit_code": {
          "type": "integer",
          "description": "The program's exit code, or -1 if it has none, as when a signal ended it."
        }
      },
      "description": "How the terminal's program exited. Null while it is still running, and for a terminal that didn't start a program of its own.",
